"""Preserve an approved, immutable selection of large admission evidence without overwriting raw files.

    python3 .../preserve_evidence.py plan --include CLOSED_SCOPE --output .../selection-pretime-v1.json
    python3 .../preserve_evidence.py preserve --selection .../selection-pretime-v1.json --approved-plan-sha256 SHA --output .../preserved-pretime-v1
    python3 .../preserve_evidence.py verify --archive .../preserved-pretime-v1
    python3 .../preserve_evidence.py restore --archive .../preserved-pretime-v1

All paths in the manifest are relative to this study. Restore accepts an optional
--destination directory for an independent round-trip check or relocated recovery.
"""

import argparse
import gzip
import hashlib
import json
import os
from pathlib import Path, PurePosixPath
import subprocess
import tempfile
import time

HERE = Path(__file__).resolve().parent
PHASE = HERE.parent
ROOT = HERE.parents[2]
MIN_BYTES = 500 * 1024
MAX_OBJECT_BYTES = 512 * 1024
RAW_PART_BYTES = 384 * 1024
EXTENSIONS = {'.json', '.jsonl', '.log', '.xml', '.txt'}
EXCLUDED_COMPONENTS = {'classes', 'test-classes', 'emitted-classes', 'target', 'artifacts',
                       'generated-classes', 'generated-binaries', 'generated-binary',
                       'binary', 'binaries', 'dependency-archive', '__pycache__'}


def require(condition, message):
    if not condition:
        raise ValueError(message)


def digest(data):
    return hashlib.sha256(data).hexdigest()


def sha(path):
    result = hashlib.sha256()
    with path.open('rb') as stream:
        for block in iter(lambda: stream.read(1 << 20), b''):
            result.update(block)
    return result.hexdigest()


def write_json(path, value):
    with path.open('x') as stream:
        json.dump(value, stream, indent=2, sort_keys=True)
        stream.write('\n')


def safe_path(base, relative):
    name = PurePosixPath(relative)
    require(relative and name.as_posix() == relative and not name.is_absolute()
            and '..' not in name.parts and '.' not in name.parts,
            'Unsafe manifest path: ' + relative)
    require('\n' not in relative and '\r' not in relative and '\\' not in relative,
            'Unsupported manifest path: ' + relative)
    path = base / name
    require(path.resolve().is_relative_to(base.resolve()), 'Path escapes destination: ' + relative)
    for ancestor in (path, *path.parents):
        if ancestor == base:
            break
        require(not ancestor.is_symlink(), 'Refusing symlink: ' + str(ancestor))
    return path


def eligible_paths():
    output = subprocess.check_output(['git', 'ls-files', '--others', '--exclude-standard', '-z', '--',
                                      str(PHASE.relative_to(ROOT))], cwd=ROOT)
    selected = []
    for name in output.split(b'\0'):
        if not name:
            continue
        path = ROOT / os.fsdecode(name)
        relative = path.relative_to(PHASE)
        if path.suffix not in EXTENSIONS or any(p in EXCLUDED_COMPONENTS or p.startswith('preserved-')
                                              for p in relative.parts):
            continue
        if path.is_file() and path.stat().st_size > MIN_BYTES:
            safe_path(PHASE, relative.as_posix())
            selected.append(path)
    return sorted(selected)


def plan(output, scopes):
    require(output.is_relative_to(HERE), 'Keep the selection receipt under this study recovery directory')
    require(not output.exists(), 'Refusing to replace an existing selection receipt')
    roots = [scope.resolve(strict=True) for scope in scopes]
    require(roots and all(root.is_relative_to(PHASE) for root in roots), 'Closed scopes must be inside this study')
    selected = [path for path in eligible_paths()
                if any(path == root or path.is_relative_to(root) for root in roots)]
    require(selected, 'No eligible untracked evidence in the declared closed scopes')
    records = []
    for path in selected:
        before = path.stat()
        checksum = sha(path)
        after = path.stat()
        require((before.st_size, before.st_mtime_ns, before.st_ino) ==
                (after.st_size, after.st_mtime_ns, after.st_ino), 'Evidence changed while planning: ' + str(path))
        records.append({'path': path.relative_to(PHASE).as_posix(), 'bytes': after.st_size,
                        'sha256': checksum})
    result = {'format': 1, 'scope': 'admission-followup-preservation-selection',
              'createdEpochNs': time.time_ns(),
              'gitHead': subprocess.check_output(['git', 'rev-parse', 'HEAD'], cwd=ROOT, text=True).strip(),
              'declaredClosedScopes': [root.relative_to(PHASE).as_posix() for root in roots],
              'preserverSha256': sha(Path(__file__)), 'minimumBytesExclusive': MIN_BYTES,
              'extensions': sorted(EXTENSIONS), 'gitUntrackedAndNotIgnored': True,
              'files': records, 'rawFilesChanged': False, 'compressionPerformed': False}
    output.parent.mkdir(parents=True, exist_ok=True)
    write_json(output, result)
    return {'selection': str(output), 'selectionSha256': sha(output), 'files': len(records),
            'rawBytes': sum(record['bytes'] for record in records), 'compressionPerformed': False}


def approved_selection(path, expected_sha):
    require(sha(path) == expected_sha, 'Approved selection receipt changed')
    value = json.loads(path.read_text())
    require(value['format'] == 1 and value['scope'] == 'admission-followup-preservation-selection',
            'Wrong selection receipt')
    require(value['preserverSha256'] == sha(Path(__file__)), 'Preservation helper changed after selection')
    require(value['minimumBytesExclusive'] == MIN_BYTES and value['extensions'] == sorted(EXTENSIONS)
            and value['gitUntrackedAndNotIgnored'] is True, 'Selection rules changed')
    records = value['files']
    names = [record['path'] for record in records]
    require(names and names == sorted(set(names)), 'Empty, duplicate or unsorted selection')
    eligible = set(eligible_paths())
    paths = []
    for record in records:
        source = safe_path(PHASE, record['path'])
        require(source in eligible, 'Selection is no longer eligible/untracked: ' + record['path'])
        require(source.stat().st_size == record['bytes'] and sha(source) == record['sha256'],
                'Approved evidence changed: ' + record['path'])
        paths.append(source)
    return value, paths


def load_manifest(archive):
    manifest_file = archive / 'manifest.json'
    expected = (archive / 'MANIFEST.sha256').read_text().strip()
    require(expected == sha(manifest_file), 'Manifest checksum mismatch')
    manifest = json.loads(manifest_file.read_text())
    require(manifest['format'] == 1 and manifest['scope'] == 'admission-followup-large-text-evidence',
            'Unexpected evidence manifest')
    paths = [record['path'] for record in manifest['files']]
    require(paths and len(paths) == len(set(paths)), 'Empty or duplicate manifest paths')
    return manifest


def restored_bytes(archive, record):
    result = bytearray()
    require(record['parts'], 'Missing archive parts: ' + record['path'])
    for part in record['parts']:
        path = safe_path(archive, part['path'])
        encoded = path.read_bytes()
        require(len(encoded) == part['compressedBytes'] <= MAX_OBJECT_BYTES,
                'Incorrect or oversized compressed part: ' + str(path))
        require(digest(encoded) == part['compressedSha256'], 'Compressed checksum mismatch: ' + str(path))
        decoded = gzip.decompress(encoded)
        require(len(decoded) == part['uncompressedBytes'] and digest(decoded) == part['uncompressedSha256'],
                'Restored part mismatch: ' + str(path))
        result.extend(decoded)
    require(len(result) == record['bytes'] and digest(result) == record['sha256'],
            'Restored file mismatch: ' + record['path'])
    return result


def verify(archive, destination):
    manifest = load_manifest(archive)
    matched, missing, total = 0, 0, 0
    for record in manifest['files']:
        restored_bytes(archive, record)
        target = safe_path(destination, record['path'])
        if target.exists():
            require(target.is_file() and target.stat().st_size == record['bytes']
                    and sha(target) == record['sha256'],
                    'Refusing different existing bytes: ' + str(target))
            matched += 1
        else:
            missing += 1
        total += record['bytes']
    return manifest, {'files': len(manifest['files']), 'bytes': total,
                      'existingMatched': matched, 'missingRestorable': missing}


def restore(archive, destination):
    # Validate every part and every existing file before creating any missing file.
    manifest, result = verify(archive, destination)
    restored = 0
    for record in manifest['files']:
        target = safe_path(destination, record['path'])
        if target.exists():
            require(target.is_file() and sha(target) == record['sha256'],
                    'Refusing changed existing bytes: ' + str(target))
            continue
        target.parent.mkdir(parents=True, exist_ok=True)
        data = restored_bytes(archive, record)
        temporary = None
        try:
            with tempfile.NamedTemporaryFile(prefix='.evidence-restore-', dir=target.parent, delete=False) as stream:
                temporary = Path(stream.name)
                stream.write(data)
                stream.flush()
                os.fsync(stream.fileno())
            try:
                os.link(temporary, target)  # Atomic publication; an existing target is never replaced.
                restored += 1
            except FileExistsError:
                require(target.is_file() and sha(target) == record['sha256'],
                        'Refusing concurrently created different bytes: ' + str(target))
        finally:
            if temporary is not None:
                temporary.unlink()
    _, checked = verify(archive, destination)
    return {**checked, 'restored': restored, 'existingMatchedBeforeRestore': result['existingMatched']}


def ignore_pattern(relative):
    escaped = ''.join('\\' + char if char in '*?[] #!' else char for char in relative)
    return '/' + escaped


def preserve(output, append_ignore, selection, approved_sha):
    require(output.is_relative_to(HERE), 'Archive must be under this study\'s recovery directory')
    require(not output.exists(), 'Refusing to replace an existing archive: ' + str(output))
    selection_value, selected = approved_selection(selection, approved_sha)
    expected_files = {record['path']: record for record in selection_value['files']}
    ignore_file = PHASE / '.gitignore'
    ignore_before = sha(ignore_file) if ignore_file.exists() else None
    script_before = sha(Path(__file__))
    output.mkdir(parents=True)
    (output / 'objects').mkdir()
    try:
        records = []
        for index, source in enumerate(selected):
            data = source.read_bytes()
            original_sha = digest(data)
            expected_file = expected_files[source.relative_to(PHASE).as_posix()]
            require(original_sha == expected_file['sha256'] and len(data) == expected_file['bytes'],
                    'Approved evidence changed before compression: ' + str(source))
            encoded = gzip.compress(data, compresslevel=9, mtime=0)
            raw_parts = [data] if len(encoded) <= MAX_OBJECT_BYTES else [
                data[offset:offset + RAW_PART_BYTES] for offset in range(0, len(data), RAW_PART_BYTES)]
            parts = []
            for part_index, raw in enumerate(raw_parts):
                compressed = encoded if len(raw_parts) == 1 else gzip.compress(raw, compresslevel=9, mtime=0)
                require(len(compressed) <= MAX_OBJECT_BYTES, 'Compressed part exceeds transfer bound')
                relative = f'objects/{index:03d}-{original_sha[:16]}-{part_index:03d}.gz'
                with (output / relative).open('xb') as stream:
                    stream.write(compressed)
                parts.append({'path': relative, 'compressedBytes': len(compressed),
                              'compressedSha256': digest(compressed), 'uncompressedBytes': len(raw),
                              'uncompressedSha256': digest(raw)})
            require(sha(source) == original_sha, 'Raw evidence changed during compression: ' + str(source))
            records.append({'path': source.relative_to(PHASE).as_posix(), 'bytes': len(data),
                            'sha256': original_sha, 'parts': parts})
        manifest = {'format': 1, 'scope': 'admission-followup-large-text-evidence',
                    'approvedSelection': {'path': str(selection), 'sha256': approved_sha,
                                          'declaredClosedScopes': selection_value['declaredClosedScopes']},
                    'createdEpochNs': time.time_ns(), 'gitHead': subprocess.check_output(
                        ['git', 'rev-parse', 'HEAD'], cwd=ROOT, text=True).strip(),
                    'phaseRelativeToRepository': PHASE.relative_to(ROOT).as_posix(),
                    'selection': {'gitUntrackedAndNotIgnored': True, 'extensions': sorted(EXTENSIONS),
                                  'minimumBytesExclusive': MIN_BYTES,
                                  'excludedPathComponents': sorted(EXCLUDED_COMPONENTS)},
                    'maximumCompressedObjectBytes': MAX_OBJECT_BYTES, 'rawFilesRemoved': False,
                    'preserverSha256': script_before, 'files': records}
        write_json(output / 'manifest.json', manifest)
        with (output / 'MANIFEST.sha256').open('x') as stream:
            stream.write(sha(output / 'manifest.json') + '\n')
        _, verification = verify(output, PHASE)
        require(verification['missingRestorable'] == 0, 'A raw file disappeared during preservation')
        require(sha(Path(__file__)) == script_before, 'Preservation helper changed during execution')
        ignore_change = None
        block = '\n# Raw evidence preserved losslessly in ' + output.relative_to(PHASE).as_posix() + '.\n'
        block += '\n'.join(ignore_pattern(record['path']) for record in records) + '\n'
        with (output / 'ignore-append.txt').open('x') as stream:
            stream.write(block)
        if append_ignore:
            require((sha(ignore_file) if ignore_file.exists() else None) == ignore_before,
                    'Study .gitignore changed concurrently; append separately after review')
            with ignore_file.open('ab') as stream:
                stream.write(block.encode())
            ignore_change = {'path': '.gitignore', 'beforeSha256': ignore_before, 'afterSha256': sha(ignore_file),
                             'exactPathCount': len(records), 'appendOnly': True}
        _, checked = verify(output, PHASE)
        parts = [part for record in records for part in record['parts']]
        receipt = {**checked, 'manifestSha256': sha(output / 'manifest.json'),
                   'compressedObjectCount': len(parts),
                   'compressedBytes': sum(part['compressedBytes'] for part in parts),
                   'largestCompressedObjectBytes': max(part['compressedBytes'] for part in parts),
                   'rawFilesUnchanged': True, 'ignoreChange': ignore_change}
        write_json(output / 'verification.json', receipt)
        return receipt
    except Exception as error:
        write_json(output / 'failure.json', {'type': type(error).__name__, 'message': str(error),
                                           'partialArchivePreserved': True})
        raise


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    commands = parser.add_subparsers(dest='command', required=True)
    choose = commands.add_parser('plan')
    choose.add_argument('--include', type=Path, action='append', required=True,
                        help='Explicit closed file/directory approved by the coordinator; never an active pilot')
    choose.add_argument('--output', type=Path, required=True)
    save = commands.add_parser('preserve')
    save.add_argument('--output', type=Path, required=True)
    save.add_argument('--selection', type=Path, required=True)
    save.add_argument('--approved-plan-sha256', required=True)
    save.add_argument('--append-ignore', action='store_true',
                      help='Append exact raw paths only after coordinator authorization; default only writes a proposal')
    for name in ('verify', 'restore'):
        command = commands.add_parser(name)
        command.add_argument('--archive', type=Path, required=True)
        command.add_argument('--destination', type=Path, default=PHASE)
    args = parser.parse_args()
    if args.command == 'plan':
        result = plan(args.output.resolve(), args.include)
    elif args.command == 'preserve':
        result = preserve(args.output.resolve(), args.append_ignore, args.selection.resolve(strict=True),
                          args.approved_plan_sha256)
    else:
        archive, destination = args.archive.resolve(), args.destination.resolve()
        result = restore(archive, destination) if args.command == 'restore' else verify(archive, destination)[1]
    print(json.dumps(result, indent=2, sort_keys=True))


if __name__ == '__main__':
    main()
